 CREATE OR REPLACE FUNCTION public.fn_eliminar_borrador_solicitud_traspaso(IN p_id_solicitud bigint,IN p_id_empresa integer,IN p_id_usuario integer)
    RETURNS boolean
    LANGUAGE 'plpgsql'
    VOLATILE
    PARALLEL UNSAFE
    COST 100
    
AS $BODY$
DECLARE
    v_id_sucursal INTEGER;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM public.cat_usuarios u
        WHERE u.id = p_id_usuario
          AND u.id_empresa = p_id_empresa
          AND u.enable = TRUE
    ) THEN
        RAISE EXCEPTION 'El usuario no esta activo o pertenece a otra empresa';
    END IF;

    SELECT st.id_sucursal_solicitante INTO v_id_sucursal
    FROM public.solicitudes_traspaso st
    WHERE st.id_solicitud = p_id_solicitud
      AND st.id_empresa = p_id_empresa
      AND st.creado_por = p_id_usuario
      AND st.estatus = 'Borrador'
    FOR UPDATE;

    IF v_id_sucursal IS NULL THEN
        RAISE EXCEPTION 'El borrador no existe o no pertenece al usuario';
    END IF;

    DELETE FROM public.solicitud_traspaso_detalle
    WHERE id_empresa = p_id_empresa
      AND id_solicitud IN (
          SELECT st.id_solicitud
          FROM public.solicitudes_traspaso st
          WHERE st.id_empresa = p_id_empresa
            AND st.creado_por = p_id_usuario
            AND st.id_sucursal_solicitante = v_id_sucursal
            AND st.estatus = 'Borrador'
      );

    DELETE FROM public.solicitudes_traspaso
    WHERE id_empresa = p_id_empresa
      AND creado_por = p_id_usuario
      AND id_sucursal_solicitante = v_id_sucursal
      AND estatus = 'Borrador';

    RETURN TRUE;
END;
$BODY$;
CREATE OR REPLACE PROCEDURE public.reportes_landy_ventas(IN p_id_empresa integer, IN p_fecha_inicio date, IN p_fecha_fin date, IN p_busqueda text, IN p_limite integer, IN p_desplazamiento integer, IN p_id_sucursal integer, IN p_origen_venta text, IN p_tipo_precio text, INOUT p_result jsonb)
    LANGUAGE 'plpgsql'
    
AS $BODY$
BEGIN
  WITH lineas AS (
    SELECT d.id, v.id AS id_venta, v.folio, v.fecha_venta AS fecha,
      v.nombre_cliente AS cliente,
      COALESCE(vendedor_persona.nombres, 'Sin vendedor') AS vendedor,
      COALESCE(cajero_persona.nombres, 'Sin cajero') AS cajero,
      v.metodo_pago, v.credito_monto, v.estatus_venta, v.total AS total_venta,
      COALESCE(e.nombre_corto, e.nombre_completo, v.nombre_establecimiento, v.id_establecimiento) AS sucursal,
      d.descripcion_producto AS producto, d.cantidad, d.unidad_medida,
      d.precio_unitario, d.importe_linea AS importe,
      COALESCE(v.descuento_autorizado, FALSE) AS descuento_autorizado,
      NULLIF(TRIM(v.descuento_motivo), '') AS descuento_motivo,
      (NULLIF(d.promocion_aplicada->>'id', '') IS NOT NULL) AS descuento_por_oferta,
      CASE
        WHEN NULLIF(d.promocion_aplicada->>'combo_id', '') IS NOT NULL THEN 'COMBO'
        WHEN NULLIF(d.promocion_aplicada->>'id', '') IS NOT NULL THEN 'PROMOCION'
        ELSE 'REGULAR'
      END AS origen_venta,
      CASE
        WHEN NULLIF(d.promocion_aplicada->>'combo_id', '') IS NOT NULL THEN 'Combo'
        WHEN NULLIF(d.promocion_aplicada->>'id', '') IS NOT NULL THEN 'Promoción'
        ELSE 'Venta regular'
      END AS origen_venta_label,
      NULLIF(d.promocion_aplicada->>'combo_nombre', '') AS combo,
      CASE
        WHEN NULLIF(d.promocion_aplicada->>'combo_id', '') IS NOT NULL THEN 'NO_APLICA'
        WHEN UPPER(COALESCE(NULLIF(d.tipo_precio_aplicado, ''), precio_historico.clave, ''))
          IN ('MINORISTA', 'PUBLICO_GENERAL') THEN 'MINORISTA'
        WHEN COALESCE(NULLIF(d.tipo_precio_aplicado, ''), precio_historico.clave) IS NOT NULL THEN 'MAYORISTA'
        WHEN NULLIF(d.promocion_aplicada->>'id', '') IS NOT NULL THEN 'MINORISTA'
        ELSE 'SIN_IDENTIFICAR'
      END AS tipo_precio,
      CASE
        WHEN NULLIF(d.promocion_aplicada->>'combo_id', '') IS NOT NULL THEN 'No aplica (combo)'
        WHEN UPPER(COALESCE(NULLIF(d.tipo_precio_aplicado, ''), precio_historico.clave, ''))
          IN ('MINORISTA', 'PUBLICO_GENERAL') THEN 'Minorista'
        ELSE COALESCE(NULLIF(d.tipo_precio_nombre, ''), precio_historico.nombre,
          CASE WHEN NULLIF(d.promocion_aplicada->>'id', '') IS NOT NULL THEN 'Minorista' END,
          'Sin identificar')
      END AS tipo_precio_label,
      SUM(GREATEST(d.importe_linea, 0)) OVER (PARTITION BY v.id) AS base_venta,
      SUM(GREATEST(d.importe_linea, 0)) OVER (PARTITION BY v.id ORDER BY d.id) AS acumulado,
      ROW_NUMBER() OVER (PARTITION BY v.id ORDER BY d.id) AS posicion
    FROM public.ventas v
    JOIN public.detalle_venta d ON d.id_venta = v.id AND d.id_empresa = v.id_empresa AND d.enable = 1
    LEFT JOIN LATERAL (
      SELECT e.id, e.nombre_corto, e.nombre_completo FROM public.cat_establecimientos e
      WHERE e.id_empresa = v.id_empresa
        AND (e.codigo::text = v.id_establecimiento::text OR e.id::text = v.id_establecimiento::text)
      ORDER BY CASE WHEN e.codigo::text = v.id_establecimiento::text THEN 0 ELSE 1 END, e.id
      LIMIT 1
    ) e ON true
    LEFT JOIN LATERAL (
      SELECT tc.clave, tc.nombre
      FROM public.precios_producto_sucursal pp
      JOIN public.tipos_cliente tc ON tc.id = pp.id_tipo_cliente
      WHERE pp.id_empresa = d.id_empresa AND pp.id_producto = d.id_producto
        AND pp.id_establecimiento = e.id
        AND pp.vigencia_inicio <= d.fecha_registro
        AND (pp.vigencia_fin IS NULL OR pp.vigencia_fin >= d.fecha_registro)
        AND ABS(pp.precio - d.precio_unitario) < 0.000001
      ORDER BY pp.vigencia_inicio DESC NULLS LAST, tc.prioridad DESC, pp.id DESC
      LIMIT 1
    ) precio_historico ON true
    LEFT JOIN LATERAL (
      SELECT NULLIF(TRIM(emp.nombres), '') AS nombres
      FROM public.cat_usuarios usr JOIN public.cat_empleados emp ON emp.id = usr.id_empleado
      WHERE usr.id_empresa = v.id_empresa
        AND (usr.id_empleado::text = NULLIF(TRIM(v.vendedor::text), '')
          OR usr.id::text = NULLIF(TRIM(v.vendedor::text), '')
          OR LOWER(TRIM(usr.username)) = LOWER(NULLIF(TRIM(v.vendedor::text), ''))
          OR LOWER(TRIM(CONCAT_WS(' ', emp.nombres, emp.apellido_paterno, emp.apellido_materno)))
            = LOWER(NULLIF(TRIM(v.vendedor::text), '')))
      ORDER BY CASE WHEN usr.id_empleado::text = NULLIF(TRIM(v.vendedor::text), '') THEN 0
        WHEN usr.id::text = NULLIF(TRIM(v.vendedor::text), '') THEN 1
        WHEN LOWER(TRIM(usr.username)) = LOWER(NULLIF(TRIM(v.vendedor::text), '')) THEN 2
        ELSE 3 END, usr.id LIMIT 1
    ) vendedor_persona ON true
    LEFT JOIN LATERAL (
      SELECT NULLIF(TRIM(emp.nombres), '') AS nombres
      FROM public.cat_usuarios usr JOIN public.cat_empleados emp ON emp.id = usr.id_empleado
      WHERE usr.id_empresa = v.id_empresa
        AND (usr.id_empleado::text = NULLIF(TRIM(v.cajero::text), '')
          OR usr.id::text = NULLIF(TRIM(v.cajero::text), '')
          OR LOWER(TRIM(usr.username)) = LOWER(NULLIF(TRIM(v.cajero::text), ''))
          OR LOWER(TRIM(CONCAT_WS(' ', emp.nombres, emp.apellido_paterno, emp.apellido_materno)))
            = LOWER(NULLIF(TRIM(v.cajero::text), '')))
      ORDER BY CASE WHEN usr.id_empleado::text = NULLIF(TRIM(v.cajero::text), '') THEN 0
        WHEN usr.id::text = NULLIF(TRIM(v.cajero::text), '') THEN 1
        WHEN LOWER(TRIM(usr.username)) = LOWER(NULLIF(TRIM(v.cajero::text), '')) THEN 2
        ELSE 3 END, usr.id LIMIT 1
    ) cajero_persona ON true
    WHERE v.id_empresa = p_id_empresa AND v.enable = 1
      AND COALESCE(v.tipo_venta, 'VENTA') = 'VENTA'
      AND REPLACE(LOWER(TRIM(COALESCE(v.estatus_venta, ''))), ' ', '_') IN ('cobrada', 'reembolsada_parcial')
      AND v.fecha_venta >= p_fecha_inicio AND v.fecha_venta < (p_fecha_fin + INTERVAL '1 day')
      AND (p_id_sucursal IS NULL OR e.id = p_id_sucursal)
  ), base AS MATERIALIZED (
    SELECT id, id_venta, folio, fecha, cliente, vendedor, cajero, metodo_pago,
      credito_monto, estatus_venta, sucursal, producto, cantidad, unidad_medida,
      precio_unitario, importe, origen_venta, origen_venta_label, combo,
      tipo_precio, tipo_precio_label,
      descuento_autorizado, descuento_por_oferta,
      CASE WHEN descuento_autorizado AND descuento_por_oferta THEN 'Autorizado / Oferta'
        WHEN descuento_autorizado THEN 'Autorizado'
        WHEN descuento_por_oferta THEN 'Oferta'
        ELSE 'Sin descuento' END AS descuento_origen_label,
      CASE WHEN descuento_autorizado THEN descuento_motivo END AS descuento_motivo,
      CASE WHEN base_venta > 0 THEN
        ROUND(total_venta * acumulado / base_venta, 2)
        - ROUND(total_venta * (acumulado - GREATEST(importe, 0)) / base_venta, 2)
      WHEN posicion = 1 THEN total_venta ELSE 0 END AS importe_neto
    FROM lineas
  ), filtrados AS MATERIALIZED (
    SELECT *, importe - importe_neto AS ajuste_prorrateado FROM base
    WHERE (COALESCE(p_busqueda, '') = '' OR producto ILIKE p_busqueda OR folio ILIKE p_busqueda
      OR combo ILIKE p_busqueda)
      AND (COALESCE(p_origen_venta, '') = '' OR origen_venta = p_origen_venta)
      AND (COALESCE(p_tipo_precio, '') = '' OR tipo_precio = p_tipo_precio)
  ), pagina AS (
    SELECT * FROM filtrados ORDER BY fecha DESC, id DESC LIMIT p_limite OFFSET p_desplazamiento
  )
  SELECT jsonb_build_object(
    'total', (SELECT COUNT(*)::integer FROM filtrados),
    'resumen', jsonb_build_object(
      'importe_neto', COALESCE((SELECT SUM(importe_neto) FROM filtrados), 0),
      'ajuste_prorrateado', COALESCE((SELECT SUM(ajuste_prorrateado) FROM filtrados), 0)),
    'rows', COALESCE((SELECT jsonb_agg(p ORDER BY p.fecha DESC, p.id DESC) FROM pagina p), '[]'::jsonb)
  ) INTO p_result;
END;
$BODY$;
CREATE OR REPLACE PROCEDURE public.reportes_landy_pagos(IN p_id_empresa integer, IN p_fecha_inicio date, IN p_fecha_fin date, IN p_busqueda text, IN p_limite integer, IN p_desplazamiento integer, IN p_id_sucursal integer, IN p_origen_venta text, IN p_tipo_precio text, INOUT p_result jsonb)
    LANGUAGE 'plpgsql'
    
AS $BODY$
BEGIN
  WITH base AS MATERIALIZED (
    SELECT vp.id, vp.id_venta, vp.fecha_pago AS fecha, v.folio,
      COALESCE(NULLIF(TRIM(empleado_pago.nombres), ''), cajero_persona.nombres, 'Sin cajero') AS cajero,
      COALESCE(e.nombre_corto, e.nombre_completo, v.nombre_establecimiento, v.id_establecimiento) AS sucursal,
      v.nombre_cliente AS cliente, v.estatus_venta,
      COALESCE(vp.tipo_movimiento, 'COBRO') AS tipo_movimiento,
      CASE WHEN TRIM(COALESCE(fp.c_formapago, '')) = '03'
          OR LOWER(TRIM(COALESCE(fp.descripcion, v.metodo_pago, ''))) LIKE 'transferencia%'
        THEN 'Transferencia'
        ELSE COALESCE(fp.descripcion, fp.c_formapago, v.metodo_pago, 'Sin método') END AS metodo_pago,
      COALESCE(fp.c_formapago, v.metodo_pago) AS codigo_pago,
      vp.referencia_pago, vp.id_corte_inclusion,
      corte.folio AS folio_corte, vp.monto AS monto_original,
      detalle_venta.origen_venta, detalle_venta.origen_venta_label,
      detalle_venta.combos AS combo,
      detalle_venta.tipo_precio, detalle_venta.tipo_precio_label,
      COALESCE(v.descuento_autorizado, FALSE) AS descuento_autorizado,
      COALESCE(detalle_venta.tiene_oferta, FALSE) AS descuento_por_oferta,
      CASE WHEN COALESCE(v.descuento_autorizado, FALSE)
          AND COALESCE(detalle_venta.tiene_oferta, FALSE) THEN 'Autorizado / Oferta'
        WHEN COALESCE(v.descuento_autorizado, FALSE) THEN 'Autorizado'
        WHEN COALESCE(detalle_venta.tiene_oferta, FALSE) THEN 'Oferta'
        ELSE 'Sin descuento' END AS descuento_origen_label,
      CASE WHEN COALESCE(v.descuento_autorizado, FALSE)
        THEN NULLIF(TRIM(v.descuento_motivo), '') END AS descuento_motivo,
      detalle_venta.tiene_regular, detalle_venta.tiene_promocion, detalle_venta.tiene_combo,
      detalle_venta.tiene_minorista, detalle_venta.tiene_mayorista,
      detalle_venta.tiene_no_aplica, detalle_venta.tiene_sin_identificar,
      CASE WHEN TRIM(COALESCE(fp.c_formapago, v.metodo_pago, '')) = '01'
        THEN CASE WHEN ABS(vp.monto) - TRUNC(ABS(vp.monto)) = 0.50
          THEN vp.monto ELSE SIGN(vp.monto) * FLOOR(ABS(vp.monto) + 0.50) END
        ELSE vp.monto END AS monto_cobrado
    FROM public.venta_pagos vp
    JOIN public.ventas v ON v.id = vp.id_venta AND v.id_empresa = vp.id_empresa
    LEFT JOIN public.cat_forma_pago fp ON fp.id = vp.forma_pago
    LEFT JOIN public.cat_usuarios u ON u.id = vp.id_usuario AND u.id_empresa = vp.id_empresa
    LEFT JOIN public.cat_empleados empleado_pago ON empleado_pago.id = u.id_empleado
    LEFT JOIN LATERAL (
      SELECT NULLIF(TRIM(emp.nombres), '') AS nombres
      FROM public.cat_usuarios usr JOIN public.cat_empleados emp ON emp.id = usr.id_empleado
      WHERE usr.id_empresa = v.id_empresa
        AND (usr.id_empleado::text = NULLIF(TRIM(v.cajero::text), '')
          OR usr.id::text = NULLIF(TRIM(v.cajero::text), '')
          OR LOWER(TRIM(usr.username)) = LOWER(NULLIF(TRIM(v.cajero::text), ''))
          OR LOWER(TRIM(CONCAT_WS(' ', emp.nombres, emp.apellido_paterno, emp.apellido_materno)))
            = LOWER(NULLIF(TRIM(v.cajero::text), '')))
      ORDER BY CASE WHEN usr.id_empleado::text = NULLIF(TRIM(v.cajero::text), '') THEN 0
        WHEN usr.id::text = NULLIF(TRIM(v.cajero::text), '') THEN 1
        WHEN LOWER(TRIM(usr.username)) = LOWER(NULLIF(TRIM(v.cajero::text), '')) THEN 2
        ELSE 3 END, usr.id LIMIT 1
    ) cajero_persona ON true
    LEFT JOIN public.cat_establecimientos e ON e.id_empresa = vp.id_empresa AND e.id = vp.id_establecimiento
    LEFT JOIN public.turno_caja_cortes corte ON corte.id = vp.id_corte_inclusion AND corte.id_empresa = vp.id_empresa
    LEFT JOIN LATERAL (
      SELECT
        CONCAT_WS(' / ',
          CASE WHEN BOOL_OR(x.origen = 'REGULAR') THEN 'Venta regular' END,
          CASE WHEN BOOL_OR(x.origen = 'PROMOCION') THEN 'Promoción' END,
          CASE WHEN BOOL_OR(x.origen = 'COMBO') THEN 'Combo' END) AS origen_venta_label,
        CONCAT_WS(' / ',
          CASE WHEN BOOL_OR(x.tipo_precio = 'MINORISTA') THEN 'Minorista' END,
          CASE WHEN BOOL_OR(x.tipo_precio = 'MAYORISTA') THEN 'Mayorista' END,
          CASE WHEN BOOL_OR(x.tipo_precio = 'NO_APLICA') THEN 'No aplica (combo)' END,
          CASE WHEN BOOL_OR(x.tipo_precio = 'SIN_IDENTIFICAR') THEN 'Sin identificar' END) AS tipo_precio_label,
        CASE WHEN COUNT(DISTINCT x.origen) = 1 THEN MIN(x.origen) ELSE 'MIXTA' END AS origen_venta,
        CASE WHEN COUNT(DISTINCT x.tipo_precio) = 1 THEN MIN(x.tipo_precio) ELSE 'MIXTO' END AS tipo_precio,
        STRING_AGG(DISTINCT x.combo, ', ') FILTER (WHERE x.combo IS NOT NULL) AS combos,
        BOOL_OR(x.origen = 'REGULAR') AS tiene_regular,
        BOOL_OR(x.origen = 'PROMOCION') AS tiene_promocion,
        BOOL_OR(x.origen = 'COMBO') AS tiene_combo,
        BOOL_OR(x.es_oferta) AS tiene_oferta,
        BOOL_OR(x.tipo_precio = 'MINORISTA') AS tiene_minorista,
        BOOL_OR(x.tipo_precio = 'MAYORISTA') AS tiene_mayorista,
        BOOL_OR(x.tipo_precio = 'NO_APLICA') AS tiene_no_aplica,
        BOOL_OR(x.tipo_precio = 'SIN_IDENTIFICAR') AS tiene_sin_identificar
      FROM (
        SELECT
          CASE WHEN NULLIF(d.promocion_aplicada->>'combo_id', '') IS NOT NULL THEN 'COMBO'
            WHEN NULLIF(d.promocion_aplicada->>'id', '') IS NOT NULL THEN 'PROMOCION' ELSE 'REGULAR' END AS origen,
          (NULLIF(d.promocion_aplicada->>'id', '') IS NOT NULL) AS es_oferta,
          NULLIF(d.promocion_aplicada->>'combo_nombre', '') AS combo,
          CASE WHEN NULLIF(d.promocion_aplicada->>'combo_id', '') IS NOT NULL THEN 'NO_APLICA'
            WHEN UPPER(COALESCE(NULLIF(d.tipo_precio_aplicado, ''), ph.clave, ''))
              IN ('MINORISTA', 'PUBLICO_GENERAL') THEN 'MINORISTA'
            WHEN COALESCE(NULLIF(d.tipo_precio_aplicado, ''), ph.clave) IS NOT NULL THEN 'MAYORISTA'
            WHEN NULLIF(d.promocion_aplicada->>'id', '') IS NOT NULL THEN 'MINORISTA'
            ELSE 'SIN_IDENTIFICAR' END AS tipo_precio
        FROM public.detalle_venta d
        LEFT JOIN LATERAL (
          SELECT tc.clave FROM public.precios_producto_sucursal pp
          JOIN public.tipos_cliente tc ON tc.id = pp.id_tipo_cliente
          WHERE pp.id_empresa = d.id_empresa AND pp.id_producto = d.id_producto
            AND pp.id_establecimiento = e.id AND pp.vigencia_inicio <= d.fecha_registro
            AND (pp.vigencia_fin IS NULL OR pp.vigencia_fin >= d.fecha_registro)
            AND ABS(pp.precio - d.precio_unitario) < 0.000001
          ORDER BY pp.vigencia_inicio DESC NULLS LAST, tc.prioridad DESC, pp.id DESC LIMIT 1
        ) ph ON true
        WHERE d.id_venta = v.id AND d.id_empresa = v.id_empresa AND d.enable = 1
      ) x
    ) detalle_venta ON true
    WHERE vp.id_empresa = p_id_empresa AND v.enable = 1
      AND COALESCE(vp.tipo_movimiento, 'COBRO') IN ('COBRO', 'REEMBOLSO', 'CANCELACION')
      AND vp.fecha_pago >= p_fecha_inicio AND vp.fecha_pago < (p_fecha_fin + INTERVAL '1 day')
      AND (p_id_sucursal IS NULL OR vp.id_establecimiento = p_id_sucursal)
  ), filtrados AS MATERIALIZED (
    SELECT *, monto_cobrado - monto_original AS ajuste_efectivo FROM base
    WHERE (COALESCE(p_busqueda, '') = '' OR folio ILIKE p_busqueda OR metodo_pago ILIKE p_busqueda
      OR cajero ILIKE p_busqueda OR combo ILIKE p_busqueda)
      AND (COALESCE(p_origen_venta, '') = ''
        OR (p_origen_venta = 'REGULAR' AND tiene_regular)
        OR (p_origen_venta = 'PROMOCION' AND tiene_promocion)
        OR (p_origen_venta = 'COMBO' AND tiene_combo))
      AND (COALESCE(p_tipo_precio, '') = ''
        OR (p_tipo_precio = 'MINORISTA' AND tiene_minorista)
        OR (p_tipo_precio = 'MAYORISTA' AND tiene_mayorista)
        OR (p_tipo_precio = 'NO_APLICA' AND tiene_no_aplica)
        OR (p_tipo_precio = 'SIN_IDENTIFICAR' AND tiene_sin_identificar))
  ), pagina AS (
    SELECT * FROM filtrados ORDER BY fecha DESC, id DESC LIMIT p_limite OFFSET p_desplazamiento
  )
  SELECT jsonb_build_object(
    'total', (SELECT COUNT(*)::integer FROM filtrados),
    'resumen', jsonb_build_object(
      'monto_original', COALESCE((SELECT SUM(monto_original) FROM filtrados), 0),
      'ajuste_efectivo', COALESCE((SELECT SUM(ajuste_efectivo) FROM filtrados), 0),
      'monto_cobrado', COALESCE((SELECT SUM(monto_cobrado) FROM filtrados), 0)),
    'rows', COALESCE((SELECT jsonb_agg(p ORDER BY p.fecha DESC, p.id DESC) FROM pagina p), '[]'::jsonb)
  ) INTO p_result;
END;
$BODY$;

 END;


