 CREATE OR REPLACE PROCEDURE public.confirmarordenproduccion(
	IN p_empresa integer,
	IN p_orden bigint,
	IN p_usuario integer,
	INOUT p_resultado jsonb DEFAULT NULL::jsonb)
LANGUAGE 'plpgsql'
AS $BODY$
DECLARE
  v_orden public.cat_ordenes_produccion%ROWTYPE;
  v_padre numeric(14,3) := 0;
  v_remanente numeric(14,3) := 0;
  v_consumo numeric(14,3) := 0;
  v_consumo_stock numeric(14,3) := 0;
  v_sucursal varchar(20);
  v_stock numeric(14,3);
  v_stock_after numeric(14,3);
  v_item record;
  v_objetivo record;
  v_descuento record;
  v_lotes_disponibles numeric;
  v_reservado numeric;
  v_producto record;
  v_ubicacion record;
  v_fecha_produccion timestamp;
  v_lote_prefijo text;
  v_lote_sufijo text;
  v_lote_interno text;
  v_id_lote bigint;
  v_lotes_generados jsonb := '{}'::jsonb;
BEGIN
  p_resultado := NULL;
  SELECT * INTO v_orden
  FROM public.cat_ordenes_produccion o
  WHERE o.id_empresa = p_empresa AND o.id = p_orden AND o.enable = true
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'La orden de producción no existe' USING ERRCODE = 'P0002';
  END IF;
  IF v_orden.estatus = 'Cerrada' THEN
    SELECT jsonb_build_object('orden', to_jsonb(v_orden), 'movimientos', coalesce(jsonb_agg(to_jsonb(m) ORDER BY m.id) FILTER (WHERE m.id IS NOT NULL), '[]'::jsonb))
      INTO p_resultado
      FROM public.produccion_orden_movimientos m WHERE m.id_orden = p_orden;
    RETURN;
  END IF;
  IF v_orden.estatus NOT IN ('Borrador', 'En proceso') THEN
    RAISE EXCEPTION 'La orden no está disponible para confirmación' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.produccion_orden_pesajes p WHERE p.id_orden = p_orden AND p.enable) THEN
    RAISE EXCEPTION 'Registra los pesajes antes de confirmar la orden' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (SELECT 1 FROM public.produccion_orden_pesajes p WHERE p.id_orden = p_orden AND p.enable AND p.metodo_pesaje = 'MANUAL' AND p.id_gerente_autoriza IS NULL) THEN
    RAISE EXCEPTION 'La orden tiene pesajes manuales sin autorización' USING ERRCODE = '22023';
  END IF;

  SELECT coalesce(sum(p.kg) FILTER (WHERE p.tipo_articulo = 'ENTRADA'), 0),
         coalesce(sum(p.kg) FILTER (WHERE p.tipo_articulo = 'REMANENTE'), 0)
    INTO v_padre, v_remanente
    FROM public.produccion_orden_pesajes p WHERE p.id_orden = p_orden AND p.enable;
  v_consumo := round(greatest(v_padre - v_remanente, 0), 3);
  IF v_consumo <= 0 THEN
    RAISE EXCEPTION 'El peso consumido del producto padre debe ser mayor a cero' USING ERRCODE = '22023';
  END IF;

  FOR v_objetivo IN SELECT value FROM jsonb_array_elements(coalesce(v_orden.objetivos, '[]'::jsonb)) value LOOP
    IF NOT EXISTS (SELECT 1 FROM public.produccion_orden_pesajes p WHERE p.id_orden = p_orden AND p.enable AND p.tipo_articulo = 'SUBPRODUCTO' AND p.id_producto = (v_objetivo.value->>'id_producto')::integer) THEN
      RAISE EXCEPTION 'Falta el pesaje de un subproducto seleccionado' USING ERRCODE = '22023';
    END IF;
  END LOOP;

  SELECT e.codigo INTO v_sucursal FROM public.cat_establecimientos e
   WHERE e.id_empresa = p_empresa AND e.codigo = v_orden.id_establecimiento AND e.enable = true;
  IF v_sucursal IS NULL THEN RAISE EXCEPTION 'La sucursal de la orden no está disponible' USING ERRCODE = '22023'; END IF;
  SELECT s.stock INTO v_stock FROM public.stock_sucursal s
   WHERE s.id_producto = v_orden.id_producto AND s.id_establecimiento = v_sucursal FOR UPDATE;
  IF v_stock IS NULL OR v_stock <= 0 THEN
    RAISE EXCEPTION 'No hay stock disponible del producto padre para confirmar la orden' USING ERRCODE = '22023';
  END IF;
  IF p_empresa = 1 AND v_orden.modalidad = 'KILO' THEN
    -- Mantener el consumo parcial, limitado al stock general y a los lotes vendibles.
    PERFORM 1 FROM public.stock_sucursal_lotes l
     WHERE l.id_empresa = p_empresa AND l.id_producto = v_orden.id_producto
       AND l.id_establecimiento = v_sucursal AND l.cantidad > 0
       AND coalesce(l.estado_existencia, 'VENDIBLE') = 'VENDIBLE'
     ORDER BY l.fecha_registro, l.id FOR UPDATE;
    SELECT coalesce(sum(l.cantidad), 0) INTO v_lotes_disponibles
      FROM public.stock_sucursal_lotes l
     WHERE l.id_empresa = p_empresa AND l.id_producto = v_orden.id_producto
       AND l.id_establecimiento = v_sucursal AND l.cantidad > 0
       AND coalesce(l.estado_existencia, 'VENDIBLE') = 'VENDIBLE';
    SELECT greatest(
      coalesce((SELECT sum(r.cantidad) FROM public.stock_reserva_temporal r
        WHERE r.id_empresa = p_empresa AND r.id_producto_stock = v_orden.id_producto
          AND r.id_establecimiento = v_sucursal AND r.fecha_expira >= now()), 0),
      coalesce((SELECT sum(l.cantidad_reservada) FROM public.preorden_linea l
        JOIN public.preorden_cabecera p ON p.id = l.id_preorden AND p.enable = 1
        WHERE l.enable = 1 AND p.estatus = 'CONFIRMADA'
          AND p.fecha_hora_programada >= timezone('America/Mexico_City', now()) - interval '2 hours'
          AND l.id_producto = v_orden.id_producto AND p.codigo_establecimiento = v_sucursal), 0))
      INTO v_reservado;
    v_consumo_stock := round(least(greatest(v_stock - v_reservado, 0), v_consumo, v_lotes_disponibles), 3);
    IF v_consumo_stock <= 0 THEN
      RAISE EXCEPTION 'No hay stock vendible disponible del producto padre para confirmar la orden' USING ERRCODE = '22023';
    END IF;
    -- La función descuenta ambos inventarios una sola vez y registra los lotes consumidos.
    SELECT * INTO v_descuento FROM public.descontar_stock_producto(
      p_empresa, v_orden.id_producto::bigint, NULL::varchar, v_sucursal,
      v_consumo_stock, 'PRODUCCION_KILO'::varchar, v_orden.id_op::varchar);
    IF v_descuento.id_producto_stock IS DISTINCT FROM v_orden.id_producto::bigint
       OR v_descuento.cantidad_stock IS DISTINCT FROM v_consumo_stock
       OR v_descuento.stock_despues IS NULL THEN
      RAISE EXCEPTION 'El consumo de producción debe descontar los kilos del producto padre seleccionado' USING ERRCODE = '22023';
    END IF;
    v_consumo_stock := v_descuento.cantidad_stock;
  ELSE
    v_consumo_stock := round(least(v_stock, v_consumo), 3);
    v_stock_after := round(v_stock - v_consumo_stock, 3);
    UPDATE public.stock_sucursal SET stock = v_stock_after, fecha_modificacion = now()
     WHERE id_producto = v_orden.id_producto AND id_establecimiento = v_sucursal;
  END IF;
  v_fecha_produccion := coalesce(v_orden.fecha_inicio, timezone('America/Mexico_City', now()));
  FOR v_item IN SELECT p.id_producto, round(sum(p.kg), 3) AS kg
                  FROM public.produccion_orden_pesajes p
                 WHERE p.id_orden = p_orden AND p.enable AND p.tipo_articulo = 'SUBPRODUCTO' GROUP BY p.id_producto LOOP
    INSERT INTO public.stock_sucursal (id_producto, sku, id_establecimiento, stock, stock_min, stock_max)
    SELECT p.id, p.sku, v_sucursal, 0, 0, 0 FROM public.cat_productos p
     WHERE p.id_empresa = p_empresa AND p.id = v_item.id_producto ON CONFLICT (id_producto, id_establecimiento) DO NOTHING;
    SELECT s.stock INTO v_stock FROM public.stock_sucursal s
     WHERE s.id_producto = v_item.id_producto AND s.id_establecimiento = v_sucursal FOR UPDATE;
    v_stock_after := round(coalesce(v_stock, 0) + v_item.kg, 3);
    UPDATE public.stock_sucursal SET stock = v_stock_after, fecha_modificacion = now()
     WHERE id_producto = v_item.id_producto AND id_establecimiento = v_sucursal;
    IF p_empresa = 1 AND v_orden.modalidad IN ('KILO', 'PIEZA') THEN
      SELECT p.sku, p.nombre INTO STRICT v_producto FROM public.cat_productos p
       WHERE p.id_empresa = p_empresa AND p.id = v_item.id_producto;
      -- Reutilizar la ubicación del subproducto; si no existe, la de la materia prima.
      SELECT u.id AS id_ubicacion, u.id_zona, z.id_almacen INTO v_ubicacion
        FROM (
          SELECT s.id_ubicacion, 0 AS prioridad, now() AS fecha, 0::bigint AS id
            FROM public.stock_sucursal s WHERE s.id_producto = v_item.id_producto
             AND s.id_establecimiento = v_sucursal AND s.id_ubicacion IS NOT NULL
          UNION ALL
          SELECT l.id_ubicacion, CASE WHEN l.id_producto = v_item.id_producto THEN 1
            WHEN l.id = v_orden.id_stock_lote OR EXISTS (SELECT 1 FROM public.stock_consumo_lote cl
              WHERE cl.id_empresa = p_empresa AND cl.id_lote = l.id
                AND cl.id_establecimiento = v_sucursal AND cl.referencia = v_orden.id_op) THEN 2 ELSE 3 END,
                 l.fecha_registro, l.id
            FROM public.stock_sucursal_lotes l WHERE l.id_empresa = p_empresa
             AND l.id_establecimiento = v_sucursal
             AND l.id_producto IN (v_item.id_producto, v_orden.id_producto)
        ) ubicacion
        JOIN public.almacen_ubicaciones u ON u.id = ubicacion.id_ubicacion AND coalesce(u.enable, true)
        JOIN public.almacen_zonas z ON z.id = u.id_zona AND coalesce(z.enable, true)
        JOIN public.almacen a ON a.id = z.id_almacen AND coalesce(a.enable, true)
        JOIN public.cat_establecimientos e ON e.id = a.id_sucursal
       WHERE e.id_empresa = p_empresa AND e.codigo = v_sucursal
       ORDER BY ubicacion.prioridad, ubicacion.fecha DESC, ubicacion.id DESC LIMIT 1;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'No se encontró ubicación de inventario para el subproducto % en la sucursal %',
          v_item.id_producto, v_sucursal USING ERRCODE = '22023';
      END IF;
      -- Formato provisional basado en SKU-fecha-hora, con la orden para distinguir producción.
      v_lote_prefijo := upper(trim(both '-' from regexp_replace(
        coalesce(nullif(trim(v_producto.sku), ''), v_item.id_producto::text), '[^A-Za-z0-9_-]+', '-', 'g')));
      v_lote_sufijo := '-PRO-' || p_orden::text || '-' || to_char(v_fecha_produccion, 'YYYY-MM-DD-HH24-MI-SS');
      v_lote_interno := rtrim(left(coalesce(nullif(v_lote_prefijo, ''), 'SIN-SKU'), 80 - length(v_lote_sufijo)), '-') || v_lote_sufijo;
      INSERT INTO public.stock_sucursal_lotes
        (id_empresa, id_producto, sku, id_establecimiento, id_almacen, id_zona, id_ubicacion,
         descripcion, lote_interno, unidad, cantidad, estado_existencia, referencia, evidencia)
      VALUES (p_empresa, v_item.id_producto, coalesce(v_producto.sku, v_item.id_producto::text),
        v_sucursal, v_ubicacion.id_almacen, v_ubicacion.id_zona, v_ubicacion.id_ubicacion,
        left(v_producto.nombre, 500), v_lote_interno, 'kg', v_item.kg, 'VENDIBLE', v_orden.id_op,
        jsonb_build_object('origen', 'PRODUCCION', 'id_orden', p_orden, 'folio', v_orden.id_op,
          'modalidad', v_orden.modalidad, 'fecha_produccion', v_fecha_produccion,
          'id_producto_padre', v_orden.id_producto, 'id_usuario', p_usuario))
      RETURNING id INTO v_id_lote;
      v_lotes_generados := v_lotes_generados || jsonb_build_object(v_item.id_producto::text,
        jsonb_build_object('id_stock_lote', v_id_lote, 'lote', v_lote_interno));
      INSERT INTO public.stock_movimiento
        (id_empresa, id_producto_origen, id_producto_stock, id_establecimiento, cantidad_origen,
         cantidad_stock, tipo_movimiento, origen, referencia, stock_antes, stock_despues)
      VALUES (p_empresa, v_item.id_producto, v_item.id_producto, v_sucursal, v_item.kg, v_item.kg,
        'ENTRADA', 'PRODUCCION_' || v_orden.modalidad, v_orden.id_op, coalesce(v_stock, 0), v_stock_after);
    END IF;
  END LOOP;

  FOR v_item IN SELECT p.id, p.tipo_articulo, p.id_producto, p.kg, p.metodo_pesaje, p.id_gerente_autoriza, p.id_usuario, p.fecha_pesaje
                  FROM public.produccion_orden_pesajes p WHERE p.id_orden = p_orden AND p.enable ORDER BY p.id LOOP
    INSERT INTO public.produccion_orden_movimientos
      (id_empresa, id_orden, id_pesaje, tipo_movimiento, id_producto, cantidad_kg, metodo_pesaje, id_gerente_autoriza, id_usuario, fecha_movimiento, datos)
    VALUES (p_empresa, p_orden, v_item.id,
      CASE v_item.tipo_articulo WHEN 'ENTRADA' THEN 'CONSUMO' WHEN 'SUBPRODUCTO' THEN 'PRODUCCION' WHEN 'MERMA' THEN 'MERMA' ELSE 'REMANENTE' END,
      v_item.id_producto, v_item.kg, v_item.metodo_pesaje, v_item.id_gerente_autoriza, v_item.id_usuario, v_item.fecha_pesaje,
      jsonb_build_object('folio', v_orden.id_op, 'origen', v_item.tipo_articulo) ||
        CASE WHEN v_item.tipo_articulo = 'SUBPRODUCTO'
          THEN coalesce(v_lotes_generados->v_item.id_producto::text, '{}'::jsonb) ELSE '{}'::jsonb END);
  END LOOP;

  UPDATE public.cat_ordenes_produccion
     SET estatus = 'Cerrada', kg_mp_reales = v_consumo, fecha_cierre = now(), fecha_confirmacion = now(), confirmado_por = p_usuario,
         modificado_por = p_usuario, fecha_modificacion = now(), movimientos_confirmados = jsonb_build_object('consumo_kg', v_consumo, 'consumo_stock_kg', v_consumo_stock, 'remanente_kg', v_remanente)
   WHERE id = p_orden;
  SELECT jsonb_build_object('orden', to_jsonb(o), 'movimientos', coalesce(jsonb_agg(to_jsonb(m) ORDER BY m.id) FILTER (WHERE m.id IS NOT NULL), '[]'::jsonb))
    INTO p_resultado
    FROM public.cat_ordenes_produccion o LEFT JOIN public.produccion_orden_movimientos m ON m.id_orden = o.id
   WHERE o.id = p_orden GROUP BY o.id;
END;
$BODY$;
ALTER PROCEDURE public.confirmarordenproduccion(integer, bigint, integer, jsonb)
    OWNER TO landiadm;


CREATE OR REPLACE PROCEDURE public.updateresultadosproduccionpieza(
	IN p_empresa integer,
	IN p_orden bigint,
	IN p_version integer,
	IN p_comentarios jsonb,
	IN p_consumo jsonb,
	IN p_usuario integer,
	INOUT p_resultado jsonb DEFAULT NULL::jsonb)
LANGUAGE 'plpgsql'
AS $BODY$

BEGIN
  p_resultado := NULL;
  IF p_empresa IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION 'La empresa no permite producción por pieza' USING ERRCODE = '22023';
  END IF;
  IF p_comentarios IS NULL OR jsonb_typeof(p_comentarios) <> 'object'
    OR p_consumo IS NULL OR jsonb_typeof(p_consumo) <> 'object' THEN
    RAISE EXCEPTION 'Los resultados no son válidos' USING ERRCODE = '22023';
  END IF;
  PERFORM 1 FROM public.cat_usuarios u WHERE u.id = p_usuario AND u.enable = true FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'El usuario no está disponible' USING ERRCODE = '22023';
  END IF;

  UPDATE public.cat_ordenes_produccion AS o
  SET calculo = coalesce(o.calculo, '{}'::jsonb) || jsonb_build_object('comentarios', p_comentarios, 'consumo', p_consumo),
    modificado_por = p_usuario, fecha_modificacion = now(), version = o.version + 1
  WHERE o.id_empresa = p_empresa AND o.id = p_orden AND o.version = p_version
    AND o.estatus = 'Borrador' AND o.modalidad = 'PIEZA' AND o.enable = true
  RETURNING to_jsonb(o) INTO p_resultado;
END;
$BODY$;
ALTER PROCEDURE public.updateresultadosproduccionpieza(integer, bigint, integer, jsonb, jsonb, integer, jsonb)
    OWNER TO landiadm;


CREATE OR REPLACE PROCEDURE public.addordenproduccionkilo(
	IN p_empresa integer,
	IN p_centro character varying,
	IN p_producto integer,
	IN p_lote bigint,
	IN p_despiece integer,
	IN p_version_despiece integer,
	IN p_configuracion jsonb,
	IN p_objetivos jsonb,
	IN p_calculo jsonb,
	IN p_usuario integer,
	INOUT p_resultado jsonb DEFAULT NULL::jsonb,
	IN p_guardar_borrador boolean DEFAULT false)
LANGUAGE 'plpgsql'
AS $BODY$
DECLARE
  v_id bigint;
  v_empleado integer;
  v_lote text;
BEGIN
  p_resultado := NULL;
  IF p_empresa IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION 'La empresa no permite producción por kilo' USING ERRCODE = '22023';
  END IF;

  SELECT u.id_empleado INTO v_empleado
  FROM public.cat_usuarios u WHERE u.id = p_usuario AND u.enable = true FOR SHARE;
  IF v_empleado IS NULL THEN
    RAISE EXCEPTION 'El usuario requiere un empleado responsable activo' USING ERRCODE = '22023';
  END IF;

  PERFORM 1 FROM public.cat_establecimientos e
  WHERE e.id_empresa = p_empresa AND e.codigo = p_centro AND e.enable = true
    AND upper(btrim(e.tipo)) = 'SUCURSAL' FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'La sucursal no está disponible para producción por kilo' USING ERRCODE = '22023';
  END IF;

  PERFORM 1 FROM public.produccion_despieces d
  WHERE d.id_empresa = p_empresa AND d.id = p_despiece AND d.version = p_version_despiece
    AND d.id_producto_entrada = p_producto AND d.estado = 'ACTIVA'
    AND d.disponible_sucursales = true FOR SHARE;
  IF NOT FOUND THEN RETURN; END IF;

  IF p_configuracion IS NULL OR (p_configuracion->>'id')::integer IS DISTINCT FROM p_despiece
    OR (p_configuracion->>'version')::integer IS DISTINCT FROM p_version_despiece
    OR (p_configuracion->>'id_producto_entrada')::integer IS DISTINCT FROM p_producto THEN
    RAISE EXCEPTION 'La versión de configuración no coincide con el borrador' USING ERRCODE = '22023';
  END IF;

  v_id := nextval(pg_get_serial_sequence('public.cat_ordenes_produccion', 'id'));
  INSERT INTO public.cat_ordenes_produccion AS o
    (id, id_op, tipo_formula, id_proceso, id_empresa, modalidad, id_establecimiento, id_producto,
     id_stock_lote, id_despiece, version_despiece, configuracion, objetivos, calculo,
     creado_por, modificado_por, id_empleado_resp, fecha_inicio, kg_mp_programados, lote_mp, estatus)
  VALUES (v_id, 'PRO-' || v_id::text, 'DESPIECE', 'DESPIECE', p_empresa, 'KILO', p_centro,
    p_producto, p_lote, p_despiece::text, p_version_despiece, p_configuracion, p_objetivos,
    p_calculo, p_usuario, p_usuario, v_empleado::text, now(),
    (p_calculo->>'peso_requerido_kg')::numeric, NULL,
    CASE WHEN p_guardar_borrador THEN 'Borrador' ELSE 'En proceso' END)
  RETURNING to_jsonb(o) INTO p_resultado;
END;
$BODY$;
ALTER PROCEDURE public.addordenproduccionkilo(integer, character varying, integer, bigint, integer, integer, jsonb, jsonb, jsonb, integer, jsonb, boolean)
    OWNER TO landiadm;


CREATE OR REPLACE PROCEDURE public.deletepesajeproduccion(
	IN p_empresa integer,
	IN p_orden bigint,
	IN p_pesaje bigint,
	IN p_usuario integer,
	INOUT p_resultado jsonb DEFAULT NULL::jsonb)
LANGUAGE 'plpgsql'
AS $BODY$

BEGIN
  p_resultado := NULL;
  PERFORM 1 FROM public.cat_ordenes_produccion o
  WHERE o.id_empresa = p_empresa AND o.id = p_orden AND o.enable = true
    AND o.estatus IN ('Borrador', 'En proceso') FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;

  UPDATE public.produccion_orden_pesajes AS p
  SET enable = false, id_usuario_baja = p_usuario, fecha_baja = now()
  WHERE p.id = p_pesaje AND p.id_orden = p_orden AND p.enable = true
  RETURNING to_jsonb(p) INTO p_resultado;

  IF p_resultado IS NOT NULL THEN
    UPDATE public.cat_ordenes_produccion SET fecha_modificacion = now(), modificado_por = p_usuario WHERE id = p_orden;
  END IF;
END;
$BODY$;
ALTER PROCEDURE public.deletepesajeproduccion(integer, bigint, bigint, integer, jsonb)
    OWNER TO landiadm;


CREATE OR REPLACE PROCEDURE public.updateordenproduccionkilo(
	IN p_empresa integer,
	IN p_orden bigint,
	IN p_version integer,
	IN p_objetivos jsonb,
	IN p_calculo jsonb,
	IN p_usuario integer,
	INOUT p_resultado jsonb DEFAULT NULL::jsonb,
	IN p_guardar_borrador boolean DEFAULT false)
LANGUAGE 'plpgsql'
AS $BODY$
BEGIN
  p_resultado := NULL;
  IF p_empresa IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION 'La empresa no permite producción por kilo' USING ERRCODE = '22023';
  END IF;
  PERFORM 1 FROM public.cat_usuarios u WHERE u.id = p_usuario AND u.enable = true FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'El usuario no está disponible' USING ERRCODE = '22023';
  END IF;

  UPDATE public.cat_ordenes_produccion AS o
  SET objetivos = p_objetivos, calculo = p_calculo,
    estatus = CASE WHEN p_guardar_borrador THEN 'Borrador' ELSE 'En proceso' END,
    kg_mp_programados = (p_calculo->>'peso_requerido_kg')::numeric,
    modificado_por = p_usuario, fecha_modificacion = now(), version = o.version + 1
  WHERE o.id_empresa = p_empresa AND o.id = p_orden AND o.version = p_version
    AND o.estatus IN ('Borrador', 'En proceso') AND o.modalidad = 'KILO' AND o.enable = true
  RETURNING to_jsonb(o) INTO p_resultado;
END;
$BODY$;
ALTER PROCEDURE public.updateordenproduccionkilo(integer, bigint, integer, jsonb, jsonb, integer, jsonb, boolean)
    OWNER TO landiadm;


CREATE OR REPLACE PROCEDURE public.addpesajeproduccion(
	IN p_empresa integer,
	IN p_orden bigint,
	IN p_data jsonb,
	IN p_usuario integer,
	INOUT p_resultado jsonb DEFAULT NULL::jsonb)
LANGUAGE 'plpgsql'
AS $BODY$

DECLARE
  v_orden public.cat_ordenes_produccion%ROWTYPE;
  v_tipo text := p_data->>'tipo_articulo';
  v_producto integer := nullif(p_data->>'id_producto', '')::integer;
  v_reemplaza bigint := nullif(p_data->>'id_reemplaza', '')::bigint;
  v_clave uuid := (p_data->>'clave_idempotencia')::uuid;
BEGIN
  p_resultado := NULL;
  IF p_empresa IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION 'La empresa no permite pesajes de producción' USING ERRCODE = '22023';
  END IF;

  SELECT o.* INTO v_orden FROM public.cat_ordenes_produccion o
  WHERE o.id_empresa = p_empresa AND o.id = p_orden AND o.enable = true
    AND o.modalidad IN ('PIEZA', 'KILO') FOR UPDATE;
  IF NOT FOUND OR v_orden.estatus NOT IN ('Borrador', 'En proceso') THEN RETURN; END IF;

  SELECT to_jsonb(p) || '{"duplicado": true}'::jsonb INTO p_resultado FROM public.produccion_orden_pesajes p
  WHERE p.id_orden = p_orden AND p.clave_idempotencia = v_clave;
  IF FOUND THEN RETURN; END IF;

  IF v_reemplaza IS NOT NULL THEN
    UPDATE public.produccion_orden_pesajes p
    SET enable = false, id_usuario_baja = p_usuario, fecha_baja = now()
    WHERE p.id = v_reemplaza AND p.id_orden = p_orden AND p.enable = true
      AND p.tipo_articulo = v_tipo AND p.id_producto IS NOT DISTINCT FROM v_producto;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'El pesaje a reemplazar ya no está disponible' USING ERRCODE = '22023';
    END IF;
  ELSIF (SELECT count(*) FROM public.produccion_orden_pesajes p
      WHERE p.id_orden = p_orden AND p.enable = true AND p.tipo_articulo = v_tipo
        AND p.id_producto IS NOT DISTINCT FROM v_producto) >= 200 THEN
    RAISE EXCEPTION 'Puedes registrar hasta 200 pesajes por artículo' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.produccion_orden_pesajes AS p
    (id_empresa, id_orden, tipo_articulo, id_producto, id_stock_lote, lote, kg, metodo_pesaje,
     bascula_id, bascula_nombre, id_gerente_autoriza, clave_idempotencia, id_reemplaza, id_usuario)
  VALUES (p_empresa, p_orden, v_tipo, v_producto,
    CASE WHEN v_tipo IN ('ENTRADA', 'REMANENTE') THEN v_orden.id_stock_lote END,
    CASE WHEN v_tipo IN ('ENTRADA', 'REMANENTE') THEN v_orden.lote_mp END,
    (p_data->>'kg')::numeric, p_data->>'metodo_pesaje',
    left(nullif(p_data->>'bascula_id', ''), 100), left(nullif(p_data->>'bascula_nombre', ''), 200),
    nullif(p_data->>'id_gerente_autoriza', '')::integer, v_clave, v_reemplaza, p_usuario)
  RETURNING to_jsonb(p) INTO p_resultado;

  UPDATE public.cat_ordenes_produccion SET fecha_modificacion = now(), modificado_por = p_usuario WHERE id = p_orden;
END;
$BODY$;
ALTER PROCEDURE public.addpesajeproduccion(integer, bigint, jsonb, integer, jsonb)
    OWNER TO landiadm;


CREATE OR REPLACE PROCEDURE public.updateordenproduccionpieza(
	IN p_empresa integer,
	IN p_orden bigint,
	IN p_version integer,
	IN p_objetivos jsonb,
	IN p_usuario integer,
	INOUT p_resultado jsonb DEFAULT NULL::jsonb)
LANGUAGE 'plpgsql'
AS $BODY$

BEGIN
  p_resultado := NULL;
  IF p_empresa IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION 'La empresa no permite producción por pieza' USING ERRCODE = '22023';
  END IF;
  PERFORM 1 FROM public.cat_usuarios u WHERE u.id = p_usuario AND u.enable = true FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'El usuario no está disponible' USING ERRCODE = '22023';
  END IF;

  UPDATE public.cat_ordenes_produccion AS o
  SET objetivos = p_objetivos, modificado_por = p_usuario, fecha_modificacion = now(), version = o.version + 1
  WHERE o.id_empresa = p_empresa AND o.id = p_orden AND o.version = p_version
    AND o.estatus = 'Borrador' AND o.modalidad = 'PIEZA' AND o.enable = true
  RETURNING to_jsonb(o) INTO p_resultado;
END;
$BODY$;
ALTER PROCEDURE public.updateordenproduccionpieza(integer, bigint, integer, jsonb, integer, jsonb)
    OWNER TO landiadm;


CREATE OR REPLACE PROCEDURE public.addordenproduccionpieza(
	IN p_empresa integer,
	IN p_centro character varying,
	IN p_producto integer,
	IN p_lote bigint,
	IN p_despiece integer,
	IN p_version_despiece integer,
	IN p_configuracion jsonb,
	IN p_objetivos jsonb,
	IN p_usuario integer,
	INOUT p_resultado jsonb DEFAULT NULL::jsonb)
LANGUAGE 'plpgsql'
AS $BODY$

DECLARE
  v_id bigint;
  v_empleado integer;
  v_lote text;
  v_tipo text;
BEGIN
  p_resultado := NULL;
  IF p_empresa IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION 'La empresa no permite producción por pieza' USING ERRCODE = '22023';
  END IF;

  SELECT u.id_empleado INTO v_empleado
  FROM public.cat_usuarios u WHERE u.id = p_usuario AND u.enable = true FOR SHARE;
  IF v_empleado IS NULL THEN
    RAISE EXCEPTION 'El usuario requiere un empleado responsable activo' USING ERRCODE = '22023';
  END IF;

  SELECT upper(btrim(e.tipo)) INTO v_tipo FROM public.cat_establecimientos e
  WHERE e.id_empresa = p_empresa AND e.codigo = p_centro AND e.enable = true
    AND upper(btrim(e.tipo)) IN ('SUCURSAL', 'CEDIS') FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'El centro no está disponible para producción por pieza' USING ERRCODE = '22023';
  END IF;

  PERFORM 1 FROM public.produccion_despieces d
  WHERE d.id_empresa = p_empresa AND d.id = p_despiece AND d.version = p_version_despiece
    AND d.id_producto_entrada = p_producto AND d.estado = 'ACTIVA'
    AND CASE WHEN v_tipo = 'CEDIS' THEN d.disponible_cedis ELSE d.disponible_sucursales END FOR SHARE;
  IF NOT FOUND THEN RETURN; END IF;

  SELECT left(coalesce(nullif(l.lote_interno, ''), nullif(l.lote_proveedor, ''), l.id::text), 40)
  INTO v_lote FROM public.stock_sucursal_lotes l
  WHERE l.id = p_lote AND l.id_empresa = p_empresa
    AND l.id_establecimiento = p_centro AND l.id_producto = p_producto FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'El lote no pertenece al producto y centro seleccionados' USING ERRCODE = '22023';
  END IF;

  IF p_configuracion IS NULL OR (p_configuracion->>'id_despiece')::integer IS DISTINCT FROM p_despiece
    OR (p_configuracion->>'version_despiece')::integer IS DISTINCT FROM p_version_despiece
    OR (p_configuracion->>'id_producto_entrada')::integer IS DISTINCT FROM p_producto THEN
    RAISE EXCEPTION 'La versión de configuración no coincide con el borrador' USING ERRCODE = '22023';
  END IF;

  v_id := nextval(pg_get_serial_sequence('public.cat_ordenes_produccion', 'id'));
  INSERT INTO public.cat_ordenes_produccion AS o
    (id, id_op, tipo_formula, id_proceso, id_empresa, modalidad, id_establecimiento, id_producto,
     id_stock_lote, id_despiece, version_despiece, configuracion, objetivos,
     creado_por, modificado_por, id_empleado_resp, fecha_inicio, kg_mp_programados, lote_mp)
  VALUES (v_id, 'PRO-' || v_id::text, 'DESPIECE', 'DESPIECE', p_empresa, 'PIEZA', p_centro,
    p_producto, p_lote, p_despiece::text, p_version_despiece, p_configuracion, p_objetivos,
    p_usuario, p_usuario, v_empleado::text, now(), 0, v_lote)
  RETURNING to_jsonb(o) INTO p_resultado;
END;
$BODY$;
ALTER PROCEDURE public.addordenproduccionpieza(integer, character varying, integer, bigint, integer, integer, jsonb, jsonb, integer, jsonb)
    OWNER TO landiadm;



 END;